INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DOMAIN-001', 1, 'Temporal strategy', 'Authoritative business facts with historical reconstruction', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-TEMPORAL-PATTERN=scd2 rather than bi-temporal: synthetic sources have effective changes but no as-known correction requirement. Transaction-time reconstruction is not offered.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'domain', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DOMAIN-002', 1, 'Stable allocation', 'Authoritative business facts with historical reconstruction', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-SURROGATE-ALLOCATION=keymap: all four reference targets retain permanent natural-key allocation; no recycled identifiers.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'domain', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DOMAIN-003', 1, 'Lifecycle and audit', 'Authoritative business facts with historical reconstruction', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-DELETE-STRATEGY=soft-delete; deletion inserts a tombstone. DEC-COLUMN-STRATEGY uses canonical audit inline and table-level change evidence in Observability.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'domain', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
