INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-SEARCH-001', 1, 'Vector dimensions', 'Portable exact vector retrieval with Domain join-back', 'Server platform; embedded file; external serving application, according to capability.', 'DOUBLE PRECISION[] binds toy-lexical-v1. Real products deploy one table per dimension/model family and register each; do not mix incompatible vectors.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'search', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-SEARCH-002', 1, 'Baseline and optional pgvector', 'Portable exact vector retrieval with Domain join-back', 'Server platform; embedded file; external serving application, according to capability.', 'Exact SQL cosine similarity is the baseline. Optional pgvector HNSW/IVFFlat needs a separate extension, model contract and recall evaluation.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'search', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-SEARCH-003', 1, 'Embedding provenance', 'Portable exact vector retrieval with Domain join-back', 'Server platform; embedded file; external serving application, according to capability.', 'Toy lexical embedding is deterministic and computed in SQL for both query and source text. It demonstrates the interface, not general semantic quality. Superseded vectors use SCD2 and soft deletion.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'search', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
