INSERT INTO memory.module_registry (module_name, container_name, deployment_status, module_version, module_purpose, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('prediction', 'prediction', 'DEPLOYED', '1.0', 'Engineered historical features and reproducible model scores', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-PREDICTION-001', 1, 'Feature history', 'Engineered historical features and reproducible model scores', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-TEMPORAL-PATTERN=scd2 departs from bi-temporal: observation is availability time and feature validity cannot precede it. Retrospective feature corrections are prohibited; a production correction requirement needs bitemporal storage.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'prediction', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-PREDICTION-002', 1, 'Engineered values', 'Engineered historical features and reproducible model scores', 'Server platform; embedded file; external serving application, according to capability.', 'Only clipped aggregate spend intensity is persisted. Descriptive context is obtained by identifier join-back. Definitions and model logic belong to Semantic.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'prediction', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-PREDICTION-003', 1, 'Model and deletion', 'Engineered historical features and reproducible model scores', 'Server platform; embedded file; external serving application, according to capability.', 'Toy score is reproducible from the exact feature observation timestamp. It is not calibrated. Soft deletion preserves prior feature and model evidence.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'prediction', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
