INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-MEMORY-001', 1, 'Versioned documentation', 'Versioned design rationale and scoped agent process continuity', 'Server platform; embedded file; external serving application, according to capability.', 'DEC-TEMPORAL-PATTERN=scd2: documentation corrections supersede prior decisions; soft deletion retains withdrawn guidance.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'memory', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-MEMORY-002', 1, 'Runtime privacy', 'Versioned design rationale and scoped agent process continuity', 'Server platform; embedded file; external serving application, according to capability.', 'Runtime USER rows are restricted to session_user by native RLS. TEAM, ORGANIZATION and AGENT sharing is denied until an authenticated membership policy is deployed.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'memory', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-MEMORY-003', 1, 'Self-contained capture', 'Versioned design rationale and scoped agent process continuity', 'Server platform; embedded file; external serving application, according to capability.', 'Every module captures decisions, glossary, cookbook and release notes with provenance. Runtime stores process context and counts, never business result rows.', 'DEC-TIMESTAMP-ZONE=zone-aware UTC. Capability gaps remain visible in the trust map.', 'ACCEPTED', 'ARCHITECTURE', 'memory', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
