INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-ACCESS-001', 1, 'Three database roles', 'PostgreSQL server product', 'See rationale for considered choices.', 'Independent READ, AGENT and ADMIN NOLOGIN roles. READ and AGENT query approved views. AGENT writes its USER runtime rows and appends outcomes. ADMIN maintains the product. Login membership is assigned by the operator.', 'Login provisioning and secure server operation remain deployment obligations.', 'ACCEPTED', 'SECURITY', 'memory', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DISCOVERY-001', 1, 'Name-only bootstrap', 'PostgreSQL server product', 'See rationale for considered choices.', 'Given customer360, read semantic.data_product_registry then ordered orientation and generated manifest. Trust precedes analytical use; approved domain.v_customer is the initial business entrypoint. Product-less discovery lists the registry.', 'Login provisioning and secure server operation remain deployment obligations.', 'ACCEPTED', 'ARCHITECTURE', 'semantic', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-DOMAIN-004', 1, 'Placement and portability', 'PostgreSQL server product', 'See rationale for considered choices.', 'One database per product and environment, with six co-located schemas. Native heap storage is the baseline; external storage requires a separately governed lifecycle.', 'Login provisioning and secure server operation remain deployment obligations.', 'ACCEPTED', 'ARCHITECTURE', 'domain', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.design_decision (decision_id, decision_version, decision_title, context, alternatives, rationale, consequences, decision_status, decision_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('DD-SEMANTIC-004', 1, 'Reusable SQL delivery', 'PostgreSQL server product', 'See rationale for considered choices.', 'A small explicit Python model generates plain SQL with shared temporal fields and complete registration. The checked build.sql runs in CLI/JDBC without Python. No Jinja dependency or DDL parsing during discovery.', 'Login provisioning and secure server operation remain deployment obligations.', 'ACCEPTED', 'ARCHITECTURE', 'semantic', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.query_cookbook (recipe_id, recipe_title, use_case, target_module, query_template, complexity, is_batch, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('QC-SEMANTIC-002', 'Discover the ERD', 'Render registered relationships', 'SEMANTIC', 'SELECT source_entity, source_column, target_entity, target_column FROM semantic.v_table_relationship ORDER BY relationship_id', 'SIMPLE', FALSE, 'semantic', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
INSERT INTO memory.query_cookbook (recipe_id, recipe_title, use_case, target_module, query_template, complexity, is_batch, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('QC-CROSS-DOMAIN-SEMANTIC', 'Plan use of domain and semantic', 'Resolve surfaces and disclose area confidence for the pair before use.', 'CROSS', 'SELECT e.entity_name, e.view_name, t.confidence FROM semantic.v_entity_metadata e LEFT JOIN observability.trust_map t ON t.scope_kind=''MODULE'' AND t.scope_id=e.module_name WHERE e.module_name IN (''domain'',''semantic'') ORDER BY e.entity_name', 'MODERATE', FALSE, 'domain', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
