INSERT INTO memory.implementation_note (note_id, note_title, note_content, note_category, source_module, authored_by, source_artifact, authored_dts, valid_from_dts, valid_to_dts, is_current, is_deleted, deleted_dts, created_dts, updated_dts) VALUES ('IN-MEMORY-001', 'Runtime isolation boundary', 'RLS authenticates scope_identifier against session_user, never a caller-set session variable. Privileged owners and superusers can bypass policy; do not grant these roles to agents.', 'SECURITY', 'memory', 'reference-implementation', 'examples/customer360-postgres', '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00', 'infinity', TRUE, FALSE, NULL, '2025-01-01 00:00:00+00', '2025-01-01 00:00:00+00');
